<?php use function Studio\{e,url,platform_label,status_label}; use Studio\{Security,IntegrationSettings}; $title='บัญชีและเพจ'; ?>
<div class="page-heading"><div><div class="eyebrow">DESTINATIONS</div><h1>บัญชีและเพจ</h1><p>เพิ่มปลายทางได้ภายหลัง โดยไม่สร้าง Workflow แยกทุกเพจ</p></div></div><div class="notice mb-4">รายการที่เพิ่มด้วย ID ยังไม่ถือว่าได้รับสิทธิ์ ต้องเชื่อมผ่าน OAuth ก่อนจัดคิวอัตโนมัติ</div>
<section class="panel mb-4"><h2>เชื่อมต่อด้วยบัญชีเจ้าของเพจ/ช่อง</h2><div class="d-flex flex-wrap gap-2"><?php if(IntegrationSettings::migrated()): foreach(['meta'=>'Connect / Reconnect Facebook','google'=>'Connect / Reconnect YouTube'] as $provider=>$label): ?><form method="post" action="<?= e(url('accounts')) ?>"><?= Security::field() ?><input type="hidden" name="action" value="oauth_start"><input type="hidden" name="provider" value="<?= e($provider) ?>"><button class="btn btn-primary" type="submit"><?= e($label) ?></button></form><?php endforeach; endif; ?><a class="btn btn-outline-primary" href="<?= e(url('integrations')) ?>">ตั้งค่า App / Client / n8n</a></div><p class="small text-secondary mt-3">เลือกเพจที่อนุญาตใน Facebook OAuth ระบบนำเข้ารายการที่ได้รับสิทธิ์จริง การเพิ่มเพจไม่ต้องสร้าง Workflow ใหม่</p></section>
<section class="panel mb-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>ปลายทาง</th><th>ประเภท / ID</th><th>การเชื่อมต่อ</th><th>ใช้งาน</th><th></th></tr></thead><tbody><?php foreach($accounts as $a): ?><tr><td class="fw-semibold"><?= e($a['display_name']) ?></td><td><?= e(platform_label($a['platform'])) ?><small class="d-block text-secondary"><?= e($a['external_account_id']) ?></small></td><td><span class="badge badge-soft"><?= e(status_label($a['connection_status'])) ?></span></td><td><?= $a['enabled']?'เปิด':'ปิด' ?></td><td><?php if($a['platform']!=='facebook_personal'): ?><?php if(IntegrationSettings::migrated() && $a['connection_status']==='CONNECTED'): ?><form method="post" action="<?= e(url('accounts')) ?>" class="mb-2"><?= Security::field() ?><input type="hidden" name="action" value="disconnect_account"><input type="hidden" name="account_id" value="<?= e($a['id']) ?>"><button class="btn btn-sm btn-light" type="submit">Disconnect ใน Studio</button></form><?php endif; ?><form method="post" action="<?= e(url('accounts')) ?>"><?= Security::field() ?><input type="hidden" name="action" value="toggle_account"><input type="hidden" name="account_id" value="<?= e($a['id']) ?>"><button class="btn btn-sm btn-outline-secondary" type="submit"><?= $a['enabled']?'ปิดใช้งาน':'เปิดใช้งาน' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h2>เพิ่มรายการปลายทาง</h2><p class="text-secondary small">ใช้ ID จริงของเพจ/ช่อง เพื่อเตรียมเลือกในคอนเทนต์ ห้ามใส่ Password หรือ Token</p><form method="post" action="<?= e(url('accounts')) ?>"><?= Security::field() ?><input type="hidden" name="action" value="add_account"><div class="row"><div class="col-md-3 mb-3"><label class="form-label" for="platform">ประเภท</label><select class="form-select" id="platform" name="platform"><option value="facebook_page">Facebook Page</option><option value="youtube">YouTube Channel</option></select></div><div class="col-md-4 mb-3"><label class="form-label" for="display_name">ชื่อแสดงผล</label><input id="display_name" name="display_name" class="form-control" maxlength="190" required></div><div class="col-md-5 mb-3"><label class="form-label" for="external_account_id">Page ID / Channel ID</label><input id="external_account_id" name="external_account_id" class="form-control" maxlength="190" required><div class="form-text">Page ID เป็นตัวเลข / Channel ID ขึ้นต้นด้วย UC ไม่ใช่ @handle</div></div></div><button class="btn btn-primary" type="submit">เพิ่มรายการรอเชื่อมต่อ</button></form></section>

